#ifndef ASSETS_H
#define ASSETS_H

static const char* INDEX_HTML =
    "<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n  <meta charset=\"UTF-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n  <title>APK \xe7\xad\xbe\xe5\x90\x8d\xe6\xa0\xa1\xe9\xaa\x8c\xe7\xa7\xbb\xe9\x99\xa4\xe5\xb7\xa5\xe5\x85\xb7</title>\n  <link rel=\"stylesheet\" href=\"/static/style.css\" />\n</head>\n<body>\n  <div class=\"wrap\">\n    <header>\n      <h1>APK \xe7\xad\xbe\xe5\x90\x8d\xe6\xa0\xa1\xe9\xaa\x8c\xe7\xa7\xbb\xe9\x99\xa4\xe5\xb7\xa5\xe5\x85\xb7</h1>\n      <p class=\"subtitle\">\xe4\xb8\x8a\xe4\xbc\xa0\xe5\xae\x89\xe8\xa3\x85\xe5\x8c\x85 \xc2\xb7 \xe4\xb8\x80\xe9\x94\xae\xe5\x8e\xbb\xe9\x99\xa4\xe7\xad\xbe\xe5\x90\x8d\xe6\xa0\xa1\xe9\xaa\x8c \xc2\xb7 \xe7\x9b\xb4\xe6\x8e\xa5\xe4\xb8\x8b\xe8\xbd\xbd</p>\n    </header>\n\n    <section class=\"card\" id=\"dropZone\">\n      <div class=\"upload-icon\">\xf0\x9f\x93\xa6</div>\n      <p class=\"hint\">\xe5\xb0\x86 <strong>.apk</strong> \xe5\xae\x89\xe8\xa3\x85\xe5\x8c\x85\xe6\x8b\x96\xe6\x8b\xbd\xe5\x88\xb0\xe6\xad\xa4\xe5\xa4\x84\xef\xbc\x8c\xe6\x88\x96</p>\n      <label class=\"btn file-btn\">\n        \xe9\x80\x89\xe6\x8b\xa9\xe5\xae\x89\xe8\xa3\x85\xe5\x8c\x85\n        <input type=\"file\" id=\"fileInput\" accept=\".apk\" hidden />\n      </label>\n      <p class=\"file-name\" id=\"fileName\"></p>\n    </section>\n\n    <div class=\"actions\">\n      <button class=\"btn primary\" id=\"removeBtn\" disabled>\xe5\x8e\xbb\xe9\x99\xa4\xe7\xad\xbe\xe5\x90\x8d\xe6\xa0\xa1\xe9\xaa\x8c</button>\n      <button class=\"btn ghost\" id=\"resetBtn\" disabled>\xe9\x87\x8d\xe6\x96\xb0\xe9\x80\x89\xe6\x8b\xa9</button>\n    </div>\n\n    <section class=\"card progress-card hidden\" id=\"progressCard\">\n      <div class=\"bar\"><div class=\"bar-fill\" id=\"barFill\"></div></div>\n      <div class=\"status\" id=\"statusText\">\xe5\x87\x86\xe5\xa4\x87\xe4\xb8\xad\xe2\x80\xa6</div>\n      <pre class=\"log\" id=\"logBox\"></pre>\n      <a class=\"btn primary hidden\" id=\"downloadBtn\" href=\"#\">\xe2\xac\x87 \xe4\xb8\x8b\xe8\xbd\xbd\xe5\xa4\x84\xe7\x90\x86\xe5\x90\x8e\xe7\x9a\x84\xe5\xae\x89\xe8\xa3\x85\xe5\x8c\x85</a>\n      <p class=\"error hidden\" id=\"errorText\"></p>\n    </section>\n\n    <footer>\n      <p class=\"disclaimer\">\n        \xe2\x9a\xa0\xef\xb8\x8f \xe6\x9c\xac\xe5\xb7\xa5\xe5\x85\xb7\xe4\xbb\x85\xe4\xbe\x9b<strong>\xe5\xae\x89\xe5\x85\xa8\xe7\xa0\x94\xe7\xa9\xb6\xe3\x80\x81\xe5\xad\xa6\xe4\xb9\xa0</strong>\xef\xbc\x8c\xe4\xbb\xa5\xe5\x8f\x8a\xe5\xaf\xb9\xe8\x87\xaa\xe5\xb7\xb1\xe6\x8b\xa5\xe6\x9c\x89\xe5\x90\x88\xe6\xb3\x95\xe6\x9d\x83\xe7\x9b\x8a\xe7\x9a\x84\xe5\xba\x94\xe7\x94\xa8\xe8\xbf\x9b\xe8\xa1\x8c\xe6\xb5\x8b\xe8\xaf\x95\xe3\x80\x82\n        \xe8\xaf\xb7\xe5\x8b\xbf\xe7\x94\xa8\xe4\xba\x8e\xe4\xbe\xb5\xe7\x8a\xaf\xe4\xbb\x96\xe4\xba\xba\xe8\x91\x97\xe4\xbd\x9c\xe6\x9d\x83\xe3\x80\x81\xe7\xbb\x95\xe8\xbf\x87\xe4\xbb\x98\xe8\xb4\xb9\xe6\xa0\xa1\xe9\xaa\x8c\xe6\x88\x96\xe4\xbb\xbb\xe4\xbd\x95\xe8\xbf\x9d\xe6\xb3\x95\xe7\x94\xa8\xe9\x80\x94\xe3\x80\x82\xe4\xbd\xbf\xe7\x94\xa8\xe8\x80\x85\xe9\xa1\xbb\xe8\x87\xaa\xe8\xa1\x8c\xe6\x89\xbf\xe6\x8b\x85\xe4\xb8\x80\xe5\x88\x87\xe6\xb3\x95\xe5\xbe\x8b\xe8\xb4\xa3\xe4\xbb\xbb\xe3\x80\x82\n      </p>\n    </footer>\n  </div>\n\n  <script src=\"/static/app.js\"></script>\n</body>\n</html>\n";

static const char* APP_JS =
    "// APK \xe7\xad\xbe\xe5\x90\x8d\xe6\xa0\xa1\xe9\xaa\x8c\xe7\xa7\xbb\xe9\x99\xa4\xe5\xb7\xa5\xe5\x85\xb7 - \xe5\x89\x8d\xe7\xab\xaf\xe9\x80\xbb\xe8\xbe\x91\xef\xbc\x88\xe5\x8e\x9f\xe7\x94\x9f\xe6\x8e\xa5\xe5\x8f\xa3\xe7\x89\x88\xef\xbc\x89\n(function () {\n  const $ = (id) => document.getElementById(id);\n  const dropZone = $(\"dropZone\");\n  const fileInput = $(\"fileInput\");\n  const fileName = $(\"fileName\");\n  const removeBtn = $(\"removeBtn\");\n  const resetBtn = $(\"resetBtn\");\n  const progressCard = $(\"progressCard\");\n  const barFill = $(\"barFill\");\n  const statusText = $(\"statusText\");\n  const logBox = $(\"logBox\");\n  const downloadBtn = $(\"downloadBtn\");\n  const errorText = $(\"errorText\");\n\n  let selectedFile = null;\n  let pollTimer = null;\n\n  function setFile(file) {\n    if (!file) return;\n    if (!file.name.toLowerCase().endsWith(\".apk\")) {\n      alert(\"\xe4\xbb\x85\xe6\x94\xaf\xe6\x8c\x81 .apk \xe5\xae\x89\xe8\xa3\x85\xe5\x8c\x85\");\n      return;\n    }\n    selectedFile = file;\n    fileName.textContent = \"\xe5\xb7\xb2\xe9\x80\x89\xe6\x8b\xa9\xef\xbc\x9a\" + file.name + \"\xef\xbc\x88\" + (file.size / 1024 / 1024).toFixed(2) + \" MB\xef\xbc\x89\";\n    removeBtn.disabled = false;\n    resetBtn.disabled = false;\n  }\n\n  [\"dragenter\", \"dragover\"].forEach((ev) =>\n    dropZone.addEventListener(ev, (e) => {\n      e.preventDefault();\n      dropZone.classList.add(\"drag\");\n    })\n  );\n  [\"dragleave\", \"drop\"].forEach((ev) =>\n    dropZone.addEventListener(ev, (e) => {\n      e.preventDefault();\n      dropZone.classList.remove(\"drag\");\n    })\n  );\n  dropZone.addEventListener(\"drop\", (e) => {\n    if (e.dataTransfer.files.length) setFile(e.dataTransfer.files[0]);\n  });\n  fileInput.addEventListener(\"change\", (e) => {\n    if (e.target.files.length) setFile(e.target.files[0]);\n  });\n\n  function resetAll() {\n    selectedFile = null;\n    fileInput.value = \"\";\n    fileName.textContent = \"\";\n    removeBtn.disabled = true;\n    resetBtn.disabled = true;\n    progressCard.classList.add(\"hidden\");\n    downloadBtn.classList.add(\"hidden\");\n    errorText.classList.add(\"hidden\");\n    barFill.style.width = \"0%\";\n    logBox.textContent = \"\";\n    if (pollTimer) clearInterval(pollTimer);\n  }\n  resetBtn.addEventListener(\"click\", resetAll);\n\n  removeBtn.addEventListener(\"click\", async () => {\n    if (!selectedFile) return;\n    removeBtn.disabled = true;\n    progressCard.classList.remove(\"hidden\");\n    downloadBtn.classList.add(\"hidden\");\n    errorText.classList.add(\"hidden\");\n    logBox.textContent = \"\";\n    barFill.style.width = \"0%\";\n    statusText.textContent = \"\xe4\xb8\x8a\xe4\xbc\xa0\xe4\xb8\xad\xe2\x80\xa6\";\n\n    let jobId;\n    try {\n      // \xe4\xbb\xa5\xe5\x8e\x9f\xe5\xa7\x8b\xe4\xba\x8c\xe8\xbf\x9b\xe5\x88\xb6\xe6\x96\xb9\xe5\xbc\x8f\xe4\xb8\x8a\xe4\xbc\xa0\xe6\x96\x87\xe4\xbb\xb6\xef\xbc\x88\xe6\x97\xa0\xe9\x9c\x80 multipart\xef\xbc\x89\n      const res = await fetch(\"/api/remove\", {\n        method: \"POST\",\n        headers: { \"Content-Type\": \"application/octet-stream\" },\n        body: selectedFile,\n      });\n      const data = await res.json();\n      if (data.error) throw new Error(data.error);\n      jobId = data.job_id;\n    } catch (err) {\n      statusText.textContent = \"\xe4\xb8\x8a\xe4\xbc\xa0\xe5\xa4\xb1\xe8\xb4\xa5\";\n      errorText.textContent = err.message;\n      errorText.classList.remove(\"hidden\");\n      return;\n    }\n    poll(jobId);\n  });\n\n  function poll(jobId) {\n    if (pollTimer) clearInterval(pollTimer);\n    pollTimer = setInterval(async () => {\n      try {\n        const res = await fetch(\"/api/status/\" + jobId);\n        const data = await res.json();\n        barFill.style.width = data.progress + \"%\";\n        logBox.textContent = data.log.join(\"\\n\");\n        logBox.scrollTop = logBox.scrollHeight;\n        if (data.status === \"queued\") {\n          statusText.textContent = \"\xe6\x8e\x92\xe9\x98\x9f\xe4\xb8\xad\xe2\x80\xa6\";\n        } else if (data.status === \"processing\") {\n          statusText.textContent = \"\xe5\xa4\x84\xe7\x90\x86\xe4\xb8\xad\xe2\x80\xa6\xef\xbc\x88\xe5\x8f\x8d\xe7\xbc\x96\xe8\xaf\x91 / \xe5\x8e\xbb\xe6\xa0\xa1\xe9\xaa\x8c / \xe9\x87\x8d\xe6\x89\x93\xe5\x8c\x85 / \xe9\x87\x8d\xe7\xad\xbe\xe5\x90\x8d\xef\xbc\x89\";\n        } else if (data.status === \"done\") {\n          statusText.textContent = \"\xe2\x9c\x85 \xe5\xa4\x84\xe7\x90\x86\xe5\xae\x8c\xe6\x88\x90\";\n          clearInterval(pollTimer);\n          downloadBtn.href = \"/api/download/\" + jobId;\n          downloadBtn.classList.remove(\"hidden\");\n        } else if (data.status === \"error\") {\n          statusText.textContent = \"\xe2\x9d\x8c \xe5\xa4\x84\xe7\x90\x86\xe5\xa4\xb1\xe8\xb4\xa5\";\n          clearInterval(pollTimer);\n          errorText.textContent = data.error || \"\xe6\x9c\xaa\xe7\x9f\xa5\xe9\x94\x99\xe8\xaf\xaf\";\n          errorText.classList.remove(\"hidden\");\n        }\n      } catch (err) {\n        // \xe5\xbf\xbd\xe7\x95\xa5\xe5\x81\xb6\xe5\x8f\x91\xe7\xbd\x91\xe7\xbb\x9c\xe9\x94\x99\xe8\xaf\xaf\xef\xbc\x8c\xe7\xbb\xa7\xe7\xbb\xad\xe8\xbd\xae\xe8\xaf\xa2\n      }\n    }, 1500);\n  }\n})();\n";

static const char* STYLE_CSS =
    ":root {\n  --bg: #0f1220;\n  --card: #1a1f35;\n  --card-2: #222842;\n  --accent: #4f7cff;\n  --accent-2: #6ee7b7;\n  --text: #e6e9f5;\n  --muted: #9aa3c7;\n  --danger: #ff6b6b;\n  --radius: 14px;\n}\n\n* { box-sizing: border-box; }\n\nbody {\n  margin: 0;\n  font-family: -apple-system, \"PingFang SC\", \"Microsoft YaHei\", \"Segoe UI\", sans-serif;\n  background: radial-gradient(1200px 600px at 70% -10%, #1c2440 0%, var(--bg) 60%), var(--bg);\n  color: var(--text);\n  min-height: 100vh;\n}\n\n.wrap {\n  max-width: 640px;\n  margin: 0 auto;\n  padding: 40px 20px 60px;\n}\n\nheader { text-align: center; margin-bottom: 28px; }\nh1 { font-size: 26px; margin: 0 0 6px; letter-spacing: 1px; }\n.subtitle { color: var(--muted); margin: 0; font-size: 14px; }\n\n.card {\n  background: var(--card);\n  border: 1px solid #2a3157;\n  border-radius: var(--radius);\n  padding: 26px;\n  margin-bottom: 18px;\n}\n\n#dropZone {\n  text-align: center;\n  border: 2px dashed #38406e;\n  transition: border-color .2s, background .2s;\n}\n#dropZone.drag { border-color: var(--accent); background: #1b2240; }\n\n.upload-icon { font-size: 46px; }\n.hint { color: var(--muted); margin: 10px 0 16px; }\n.file-name { color: var(--accent-2); margin-top: 14px; font-size: 14px; min-height: 18px; }\n\n.btn {\n  display: inline-block;\n  padding: 11px 22px;\n  border-radius: 10px;\n  border: none;\n  font-size: 15px;\n  cursor: pointer;\n  text-decoration: none;\n  transition: transform .1s, opacity .2s;\n  user-select: none;\n}\n.btn:active { transform: translateY(1px); }\n.btn.primary { background: var(--accent); color: #fff; }\n.btn.ghost { background: transparent; color: var(--muted); border: 1px solid #38406e; }\n.btn:disabled { opacity: .45; cursor: not-allowed; }\n.file-btn { background: var(--card-2); color: var(--text); }\n\n.actions { display: flex; gap: 12px; justify-content: center; margin-bottom: 18px; }\n\n.progress-card { background: var(--card-2); }\n.bar {\n  height: 10px;\n  background: #11152a;\n  border-radius: 6px;\n  overflow: hidden;\n  margin-bottom: 12px;\n}\n.bar-fill {\n  height: 100%;\n  width: 0%;\n  background: linear-gradient(90deg, var(--accent), var(--accent-2));\n  transition: width .4s ease;\n}\n.status { color: var(--text); font-size: 14px; margin-bottom: 10px; }\n.log {\n  background: #0c0f1e;\n  border-radius: 8px;\n  padding: 12px;\n  height: 220px;\n  overflow-y: auto;\n  font-size: 12.5px;\n  line-height: 1.6;\n  color: #b9c2e8;\n  white-space: pre-wrap;\n  word-break: break-all;\n  margin: 0 0 14px;\n}\n.error { color: var(--danger); font-size: 14px; }\n\n.disclaimer {\n  color: var(--muted);\n  font-size: 12.5px;\n  line-height: 1.7;\n  text-align: center;\n  border-top: 1px solid #2a3157;\n  padding-top: 18px;\n}\n.disclaimer strong { color: var(--text); }\n\n.hidden { display: none !important; }\n";

#endif
